				if(s[i] != s[j]) {
					continue;
				}
				int len = j - i + 1;
				if(len <= 3) {
					dp[i][j] = true;
				} else {
					dp[i][j] = dp[i + 1][j - 1];
				}
				if(dp[i][j] && len > maxLen) {
					maxLen = len;
					start  = i;
				}
			}
		}
		return s.substr(start, maxLen);
	}
