设 `dp[i][j]` 表示 `s[i..j]` 是否为回文
- `s[i] != s[j]` → `dp[i][j] = false`
- `s[i] == s[j]` 且 `j - i <= 2` → `true`（长度 1、2、3）
- 否则 `dp[i][j] = dp[i+1][j-1]`，这里这种情况说明 `s[i] == s[j]`，可以向外拓展了
马拉车算法:
```cpp
string longestPalindromeManacher(const string& s) {
    if (s.empty()) return "";

    // 预处理：^#a#b#a#$  (^ 和 $ 作哨兵)
    string t = "^#";
    for (char c : s) { t += c; t += '#'; }
    t += '$';

    int n = t.size();
    vector<int> p(n, 0);
    int center = 0, right = 0;
    int maxLen = 0, maxCenter = 0;

    for (int i = 1; i < n - 1; ++i) {
        if (i < right)
            p[i] = min(right - i, p[2 * center - i]);

        while (t[i + p[i] + 1] == t[i - p[i] - 1]) ++p[i];

        if (i + p[i] > right) {
            center = i;
            right  = i + p[i];
        }
        if (p[i] > maxLen) {
            maxLen    = p[i];
            maxCenter = i;
        }
    }

    int start = (maxCenter - maxLen) / 2; // 映射回原串
    return s.substr(start, maxLen);
}
```

